import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Rule definition","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rule-definition.md","filePath":"reference/rule-definition.md"}`),a={name:`reference/rule-definition.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="rule-definition" tabindex="-1">Rule definition <a class="header-anchor" href="#rule-definition" aria-label="Permalink to “Rule definition”">​</a></h1><p>This document is the reference of the rule definition surface: the function that declares a rule, the shape of a rule, and the types a rule returns, as they are provided by the base vibator framework. A rule reaches files and utilities through the <a href="./vibator-namespace.html"><code>vibator</code> namespace</a>.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="#definerule">defineRule</a> — Declare a rule.</li><li><a href="#rule">Rule</a> — The shape of a rule.</li><li><a href="#report">Report</a> — The result of a rule execution.</li><li><a href="#diagnostic">Diagnostic</a> — One finding in a report.</li><li><a href="#severity">Severity</a> — The importance of a finding.</li><li><a href="#scope">scope</a> — Shared include/exclude options fragment.</li></ul><hr><h2 id="definerule" tabindex="-1">defineRule <a class="header-anchor" href="#definerule" aria-label="Permalink to “defineRule”">​</a></h2><p>Declare a rule.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>defineRule(rule: <a href="#rule">Rule</a>): <a href="#rule">Rule</a></td><td>Declares a rule and infers its options type from the schema.</td></tr></tbody></table><h2 id="rule" tabindex="-1">Rule <a class="header-anchor" href="#rule" aria-label="Permalink to “Rule”">​</a></h2><p>The shape of a rule. <code>id</code>, <code>title</code>, and <code>docs</code> are required; the rest carry defaults.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>id: string</td><td>The stable kebab-case identifier, used as the config key.</td></tr><tr><td>title: string</td><td>One line describing what the rule enforces.</td></tr><tr><td>docs: string</td><td>The path to the guideline.</td></tr><tr><td>severity?: <a href="#severity">Severity</a></td><td>The default severity. The framework applies <code>&quot;error&quot;</code> by default.</td></tr><tr><td>options?: ZodType&lt;Options&gt;</td><td>The schema that validates and defaults the rule&#39;s config block.</td></tr><tr><td>check(options: Options): <a href="#report">Report</a> | Promise&lt;<a href="#report">Report</a>&gt;</td><td>Runs the rule across the files it chooses and returns a report.</td></tr><tr><td>fix?(options: Options, report: <a href="#report">Report</a>): void | Promise&lt;void&gt;</td><td>Corrects the findings in a report. The framework calls it under <code>--write</code>.</td></tr></tbody></table><p><code>Options</code> is the type inferred from the <code>options</code> schema. A rule that declares no schema receives an empty options object.</p><p>A <code>docs</code> value resolves from the project root, such as <code>.vibator/docs/my-rule.md</code>, or from a package when prefixed with the package name, such as <code>vibator:docs/rules/no-deprecated-apis.md</code>.</p><p>A rule that implements <code>fix</code> runs it only when <code>--write</code> is enabled. The framework then drives that rule through a recheck loop, <code>check</code> → <code>fix</code> → <code>check</code>, and reports whatever findings the final <code>check</code> leaves.</p><h2 id="report" tabindex="-1">Report <a class="header-anchor" href="#report" aria-label="Permalink to “Report”">​</a></h2><p>The result of a rule execution. One rule produces one report covering every file it read.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>diagnostics: <a href="#diagnostic">Diagnostic</a>[]</td><td>Every finding from the rule execution.</td></tr></tbody></table><h2 id="diagnostic" tabindex="-1">Diagnostic <a class="header-anchor" href="#diagnostic" aria-label="Permalink to “Diagnostic”">​</a></h2><p>One finding in a report.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>file?: string</td><td>The absolute path of the finding; reporters display it relative to the project root. Omit it for a whole-project finding.</td></tr><tr><td>line?: number</td><td>The start line, or the single line where the finding is.</td></tr><tr><td>endLine?: number</td><td>The last line, when the finding spans several.</td></tr><tr><td>column?: number</td><td>The column where the finding starts.</td></tr><tr><td>message: string</td><td>What the finding reports as wrong.</td></tr><tr><td>expected?: string</td><td>The standard the rule requires.</td></tr><tr><td>fix?: string</td><td>The concrete next action that resolves it.</td></tr></tbody></table><h2 id="severity" tabindex="-1">Severity <a class="header-anchor" href="#severity" aria-label="Permalink to “Severity”">​</a></h2><p>The importance the framework assigns a finding.</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td>&quot;error&quot;</td><td>Fails the run.</td></tr><tr><td>&quot;warn&quot;</td><td>Reports the finding and keeps the run passing.</td></tr><tr><td>&quot;off&quot;</td><td>Skips the rule.</td></tr></tbody></table><h2 id="scope" tabindex="-1">scope <a class="header-anchor" href="#scope" aria-label="Permalink to “scope”">​</a></h2><p>A prebuilt options fragment for file scope. A rule extends it in its <code>options</code> to expose <code>include</code> and <code>exclude</code> with shared defaults.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>include: string[]</td><td>Glob patterns selecting the files the rule judges. Defaults to <code>[&quot;**/*.{ts,tsx,js,jsx,mjs,cjs}&quot;]</code>.</td></tr><tr><td>exclude: string[]</td><td>Glob patterns removed from that selection. Defaults to <code>[&quot;**/*.test.*&quot;, &quot;**/*.spec.*&quot;]</code>.</td></tr></tbody></table><hr><h2 id="external-types" tabindex="-1">External types <a class="header-anchor" href="#external-types" aria-label="Permalink to “External types”">​</a></h2><p>Types provided by other packages.</p><table tabindex="0"><thead><tr><th>Type</th><th>Source</th></tr></thead><tbody><tr><td>ZodType</td><td><a href="https://zod.dev" target="_blank" rel="noreferrer">zod</a></td></tr></tbody></table>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};